window.__PLANE_I18N_PATCH__=function(i18n){
  if(!i18n||i18n.__planePatched) return i18n;
  var dict=window.__PLANE_EN_I18N__||{};
  var res=window.__PLANE_I18N_RESOURCES__;
  try{
    if(res&&i18n.addResourceBundle){
      Object.keys(res).forEach(function(lng){
        Object.keys(res[lng]||{}).forEach(function(ns){
          try{i18n.addResourceBundle(lng,ns,res[lng][ns],true,true);}catch(e){}
        });
      });
    }
  }catch(e){}
  var orig=i18n.t.bind(i18n);
  i18n.t=function(key, opts){
    var r=orig.apply(this, arguments);
    if(typeof key==="string" && dict[key] && (r===key||r==null||r==="")) return dict[key];
    if(typeof r==="string" && dict[r]) return dict[r];
    if(typeof key==="string" && dict[key]) return dict[key];
    return r;
  };
  try{
    if(i18n.options){
      i18n.options.parseMissingKeyHandler=function(k){return (dict&&dict[k])||k;};
    }
  }catch(e){}
  i18n.__planePatched=true;
  try{document.documentElement.setAttribute('data-i18n-ready','1');}catch(e){}
  return i18n;
};
(function(){
  var n=0,id=setInterval(function(){
    n++;
    try{
      var i18n=window.i18n||window.i18next;
      if(i18n&&i18n.t){window.__PLANE_I18N_PATCH__(i18n);clearInterval(id);}
    }catch(e){}
    if(n>500) clearInterval(id);
  },15);
})();
